INSERT INTO email_templates (business_profile_id, name, category, subject, preheader, body, body_html, body_text, followup_stage, active, created_at, updated_at) VALUES
(1, 'Initial Outreach - Skincare/Cosmetic Formulators', 'Skincare / cosmetic formulators', 'A practical peptide sourcing partner for {{company_name}}', 'MOQ flexibility, documentation support, and clear coordination for formulation teams.', 'Hello {{contact_name}},\n\nI am reaching out from {{brand_name}} because Atlas BioLabs supports qualified B2B peptide sourcing conversations with a clear commercial process.\n\nFor formulation teams, we focus on practical next steps around MOQ flexibility, documentation support, batch transparency, and sourcing coordination.\n\nHow Atlas BioLabs can support:\n- MOQ flexibility support for early-stage or scaling programs\n- Documentation support for internal technical review\n- Batch transparency and qualified B2B supply communication\n\nIf this is relevant for {{company_name}}, we would be glad to discuss current priorities and next steps.\n\n{{default_signature}}\n\nUnsubscribe: {{unsubscribe_link}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I am reaching out from {{brand_name}} because Atlas BioLabs supports qualified B2B peptide sourcing conversations with a clear commercial process.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">For formulation teams, we focus on practical next steps around MOQ flexibility, documentation support, batch transparency, and sourcing coordination.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">How Atlas BioLabs Can Support</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">MOQ flexibility support for early-stage or scaling programs</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Documentation support for internal technical review</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 0 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0;font-size:15px;line-height:24px;color:#243548;\">Batch transparency and qualified B2B supply communication</td></tr></table></td></tr></table><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">If this is relevant for {{company_name}}, we would be glad to discuss current priorities and next steps.</p><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject=Atlas%20BioLabs%20Sourcing%20Discussion\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Discuss Sourcing Needs</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">Or reply with the product, quantity range, or documentation priorities your team is currently reviewing.</div>', 'Hello {{contact_name}},\n\nI am reaching out from {{brand_name}} because Atlas BioLabs supports qualified B2B peptide sourcing conversations with a clear commercial process.\n\nFor formulation teams, we focus on practical next steps around MOQ flexibility, documentation support, batch transparency, and sourcing coordination.\n\nHow Atlas BioLabs can support:\n- MOQ flexibility support for early-stage or scaling programs\n- Documentation support for internal technical review\n- Batch transparency and qualified B2B supply communication\n\nIf this is relevant for {{company_name}}, we would be glad to discuss current priorities and next steps.\n\nReply to: {{reply_to_email}}\n\n{{default_signature}}\n\nUnsubscribe: {{unsubscribe_link}}', 0, 1, NOW(), NOW()),
(1, 'Initial Outreach - Ingredient Distributors', 'Ingredient distributors', 'Peptide sourcing support for distribution teams at {{company_name}}', 'Documentation-ready coordination for qualified distribution conversations.', 'Hello {{contact_name}},\n\n{{brand_name}} supports distribution-focused peptide sourcing conversations with commercially clear follow-up and documentation-aware coordination.\n\nFor ingredient distributors, we keep the discussion focused on what helps a sourcing review move forward efficiently.\n\nWhat We Can Help With:\n- MOQ flexibility support where planning needs vary by opportunity\n- Documentation support for internal buyer and compliance review\n- Sourcing coordination and qualified B2B supply communication\n\nIf useful, we would be glad to learn what {{company_name}} is currently evaluating.\n\n{{default_signature}}\n\nUnsubscribe: {{unsubscribe_link}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">{{brand_name}} supports distribution-focused peptide sourcing conversations with commercially clear follow-up and documentation-aware coordination.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">For ingredient distributors, we keep the discussion focused on what helps a sourcing review move forward efficiently.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">What We Can Help With</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">MOQ flexibility support where planning needs vary by opportunity</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 12px 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0 0 12px;font-size:15px;line-height:24px;color:#243548;\">Documentation support for internal buyer and compliance review</td></tr><tr><td valign=\"top\" width=\"18\" style=\"padding:0 10px 0 0;\"><div style=\"width:10px;height:10px;background:#2E6BFF;border-radius:50%;font-size:0;line-height:0;\">&nbsp;</div></td><td style=\"padding:0;font-size:15px;line-height:24px;color:#243548;\">Sourcing coordination and qualified B2B supply communication</td></tr></table></td></tr></table><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">If useful, we would be glad to learn what {{company_name}} is currently evaluating.</p><table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 10px;\"><tr><td><a href=\"mailto:{{reply_to_email}}?subject=Atlas%20BioLabs%20Distribution%20Discussion\" style=\"display:inline-block;background:#2E6BFF;color:#FFFFFF;text-decoration:none;font-size:15px;font-weight:700;line-height:15px;padding:14px 22px;border-radius:12px;\">Review Requirements</a></td></tr></table><div style=\"font-size:14px;line-height:22px;color:#5B6B7E;\">You can also reply with the categories, documentation needs, or sourcing priorities your team is reviewing.</div>', 'Hello {{contact_name}},\n\n{{brand_name}} supports distribution-focused peptide sourcing conversations with commercially clear follow-up and documentation-aware coordination.\n\nFor ingredient distributors, we keep the discussion focused on what helps a sourcing review move forward efficiently.\n\nWhat We Can Help With:\n- MOQ flexibility support where planning needs vary by opportunity\n- Documentation support for internal buyer and compliance review\n- Sourcing coordination and qualified B2B supply communication\n\nIf useful, we would be glad to learn what {{company_name}} is currently evaluating.\n\nReply to: {{reply_to_email}}\n\n{{default_signature}}\n\nUnsubscribe: {{unsubscribe_link}}', 0, 1, NOW(), NOW()),
(1, 'Initial Outreach - Contract Manufacturers', 'Contract manufacturers', 'Supply coordination support for {{company_name}}', 'Structured sourcing support for manufacturing teams reviewing quantity, timing, and documentation.', 'Hello {{contact_name}},\n\nI am reaching out from {{brand_name}} because Atlas BioLabs supports qualified manufacturing-side sourcing conversations with a practical commercial process.\n\nFor contract manufacturers, we focus on supply coordination that is clear, documentation-aware, and easy to move through internal review.\n\nTypical Support Areas:\n- MOQ flexibility support for program planning\n- Documentation support for technical and commercial stakeholders\n- Batch transparency and sourcing coordination for qualified opportunities\n\nIf useful, we would be glad to discuss what {{company_name}} is currently working through.\n\n{{default_signature}}\n\nUnsubscribe: {{unsubscribe_link}}', '<p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">Hello {{contact_name}},</p><p style=\"margin:0 0 16px;font-size:16px;line-height:26px;color:#243548;\">I am reaching out from {{brand_name}} because Atlas BioLabs supports qualified manufacturing-side sourcing conversations with a practical commercial process.</p><p style=\"margin:0 0 22px;font-size:16px;line-height:26px;color:#243548;\">For contract manufacturers, we focus on supply coordination that is clear, documentation-aware, and easy to move through internal review.</p><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin:0 0 24px;background:#F7FAFD;border:1px solid #DCE6F2;border-radius:16px;\"><tr><td style=\"padding:20px 22px;\"><div style=\"font-size:13px;line-height:18px;font-weight:700;letter-spacing:0.2px;color:#0A1A2F;text-transform:uppercase;\">Typical Support Areas</div><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin-top:12px;\"><tr><td valign=\"top